def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

fib_values = {}
for k in range(2, 31):
    fib_values[k] = fibonacci(k)

print("F_k for k=2 to 30:")
for k in range(2, 31):
    print(f"F_{k} = {fib_values[k]}")

differences = [fib_values[k] for k in range(2, 31)]
print(f"\nList of differences {differences[:5]}...{differences[-5:]}")

